#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.assign(n, 0);
    if (n == 0) return;

    int P = 1;
    #pragma omp parallel
    {
        #pragma omp single
        { P = omp_get_num_threads(); }
    }
    if (P < 1) P = 1;
    if (P > n) P = n;

    std::vector<long long> blockSum(P, 0);
    std::vector<long long> blockOffset(P, 0);

    #pragma omp parallel num_threads(P) shared(output, blockSum, blockOffset)
    {
        const int tid = omp_get_thread_num();

        const int base = n / P;
        const int rem  = n % P;

        const int len = base + (tid < rem ? 1 : 0);
        const int start = tid * base + (tid < rem ? tid : rem);
        const int end = start + len; // exclusive

        // Pass 1: local reverse prefix sums within block (from right to left)
        long long running = 0;
        for (int i = end - 1; i >= start; --i) {
            running += static_cast<long long>(x[i]);
            output[i] = static_cast<int>(running);
        }
        blockSum[tid] = running;

        #pragma omp barrier

        // Pass 2: compute per-block offsets (sum of all blocks strictly to the right)
        #pragma omp single
        {
            long long suffix = 0;
            for (int t = P - 1; t >= 0; --t) {
                blockOffset[t] = suffix;
                suffix += blockSum[t];
            }
        }

        #pragma omp barrier

        // Pass 3: add offset to each element in block
        const long long off = blockOffset[tid];
        for (int i = start; i < end; ++i) {
            output[i] = static_cast<int>(static_cast<long long>(output[i]) + off);
        }
    }
}
