    int P = 1;
    if (omp_in_parallel()) {
        P = omp_get_num_threads(); // size of the existing team
    } else {
        P = omp_get_max_threads();
    }
    if (P < 1) P = 1;
    if (P > n) P = n;

    std::vector<long long> blockSum(P, 0);
    std::vector<long long> blockOffset(P, 0);

    auto worker = [&](int tid) {
        const int base = n / P;
        const int rem  = n % P;

